preview.modifiedContent:
{
  "name": "summarize-notes",
  "description": "For every Markdown file in the notes/ directory, write a one-paragraph summary, then combine the summaries into notes/SUMMARY.md.",
  "inputs": {
    "notes_dir": {
      "type": "string",
      "description": "Path to the directory containing the Markdown notes to summarize.",
      "default": "notes"
    },
    "output_file": {
      "type": "string",
      "description": "Path where the combined summary document will be written.",
      "default": "notes/SUMMARY.md"
    }
  },
  "steps": [
    {
      "id": "list_markdown_files",
      "name": "List Markdown files",
      "prompt": "List every Markdown file (files ending in .md) in the {{inputs.notes_dir}} directory. Exclude {{inputs.output_file}} itself if present. Return the result as a plain list of file paths, one per line."
    },
    {
      "id": "summarize_each_file",
      "name": "Summarize each Markdown file",
      "prompt": "For each Markdown file listed below, read its contents and write a single concise one-paragraph summary that captures the main points. Label each summary with the file name.\n\nFiles to summarize:\n{{steps.list_markdown_files.output}}"
    },
    {
      "id": "combine_summaries",
      "name": "Combine summaries into SUMMARY.md",
      "prompt": "Combine the per-file summaries below into a single Markdown document and write it to {{inputs.output_file}}. Use a top-level heading (for example '# Notes Summary'), then a section for each source file with its file name as a subheading followed by that file's one-paragraph summary.\n\nSummaries:\n{{steps.summarize_each_file.output}}"
    }
  ]
}

